shader:
// Light Leak - organic film burn that sweeps across the frame and hides the cut in the light.
// Params: tint (0 = white light, 1 = the original warm red-orange leak), intensity (leak density),
// direction (deg, drift of the leak), grain (film grain, fades with the leak).
// The shape, sweep, defocus and grain are the original leak's; tint only changes the colour of the light.
// Look: the leak is an exposure field X (domain-warped, log-normal-ish: thin red edge, orange body, small hot core).
// Its colour comes from a film-like response (red saturates first, green later, blue last) and the plate under it goes
// through an orange gel + amber burn valleys, so bright footage turns orange-amber with a warm-white core, not cream.

const float LL_CUT = 0.5;
// envelope: ease-in pow(p/0.5, 2.4); ease-out pow(1-u, REL) for plate effects, pow(1-u, RELL) for the light itself
const float LL_REL = 2.2;
const float LL_RELL = 2.6;
// leak exposure field
const float LL_GAIN = 2.2;
const float LL_MASS = 7.0;
const float LL_POW = 3.5;
const float LL_WASH_FLOOR = 0.2;
const float LL_ADAPT = 0.55;            // light multiplier on bright plates (global plate brightness)
// film response of the emitted light: G and B rise late (toe exponents), warmth moves orange -> golden
const float LL_KG_O = 0.105;
const float LL_KG_G = 0.25;
const float LL_KB_O = 0.07;
const float LL_KB_G = 0.10;
const float LL_NG = 1.8;
const float LL_NB = 3.5;
const float LL_GLIN = 0.3;              // a little green at low exposure: the thin edge is red-orange, not pink
const vec3 LL_W_O = vec3(1.0, 0.20, 0.035);
const vec3 LL_W_G = vec3(1.0, 0.48, 0.10);
// plate under the leak: orange gel, amber burn valleys, cover where the light is dense
const vec3 LL_GEL_O = vec3(1.0, 0.50, 0.12);
const vec3 LL_GEL_G = vec3(1.0, 0.76, 0.28);
const float LL_GEL_AMT = 0.9;
const float LL_GEL_ENV = 0.4;
const float LL_GEL_X = 1.2;
const vec3 LL_BURN = vec3(0.85, 0.50, 0.18);
const float LL_VALLEY = 0.3;
const float LL_COVER = 0.6;
const float LL_COV0 = 0.5;
const float LL_COV1 = 5.0;
const float LL_KNEE = 0.45;
const float LL_WARM = 0.45;             // warmth of the warm look (tint = 1): the original default
// motion: B settles (zoom 1.06 -> 1.0) with pow(x, EB); defocus radii for A / B
const float LL_EB = 4.0;
const float LL_DEF = 0.022;
const float LL_DEFP = 2.0;
const float LL_DEFB = 0.03;
const float LL_DEFPB = 1.3;

vec2 llHash22(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float llHash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// gradient noise, roughly -1..1
float llNoise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    vec2 ga = llHash22(i) * 2.0 - 1.0;
    vec2 gb = llHash22(i + vec2(1.0, 0.0)) * 2.0 - 1.0;
    vec2 gc = llHash22(i + vec2(0.0, 1.0)) * 2.0 - 1.0;
    vec2 gd = llHash22(i + vec2(1.0, 1.0)) * 2.0 - 1.0;
    float va = dot(ga, f);
    float vb = dot(gb, f - vec2(1.0, 0.0));
    float vc = dot(gc, f - vec2(0.0, 1.0));
    float vd = dot(gd, f - vec2(1.0, 1.0));
    return mix(mix(va, vb, u.x), mix(vc, vd, u.x), u.y) * 1.6;
}

float llFbm(vec2 p) {
    float s = 0.0;
    float a = 0.5;
    const mat2 R = mat2(0.80, 0.60, -0.60, 0.80);
    const int OCT = 4;
    for (int i = 0; i < OCT; i++) {
        s += a * llNoise(p);
        p = R * p * 2.03 + vec2(3.1, 1.7);
        a *= 0.42;
    }
    return s;
}

vec3 llToLin(vec3 c) { return pow(max(c, vec3(0.0)), vec3(2.2)); }
vec3 llToGam(vec3 c) { return pow(max(c, vec3(0.0)), vec3(1.0 / 2.2)); }
float llMax3(vec3 c) { return max(c.r, max(c.g, c.b)); }

// hue-preserving film shoulder: the brightest channel rolls off, the others keep their ratio to it,
// so orange light stays orange instead of skewing to lemon-cream (the white core comes from the light's own response)
vec3 llTone(vec3 x, float knee) {
    float mx = llMax3(x);
    float r = max(1.0 - knee, 1e-4);
    float sh = mx > knee ? knee + r * (1.0 - exp(-(mx - knee) / r)) : mx;
    return x * (sh / max(mx, 1e-4));
}

// push-in + drift of each plate: e = 0 at rest, 1 at the cut; sgn keeps the drift travelling one way through the cut
vec2 llPlateUV(vec2 uv, float e, vec2 dir, float sgn) {
    float z = 1.0 + 0.06 * e;
    vec2 c = (uv - 0.5) / z + 0.5;
    return c - sgn * dir * 0.02 * e;
}

// mean brightness of a plate from 6 fixed taps (sRGB luma); global, so the light never imprints the plate's shapes
float llMeanA() {
    float acc = 0.0;
    const int NM = 6;
    for (int i = 0; i < NM; i++) {
        float fi = float(i);
        acc += luma(getA(vec2(fract(0.17 + fi * 0.618034), (fi + 0.5) / float(NM))).rgb);
    }
    return acc / float(NM);
}
float llMeanB() {
    float acc = 0.0;
    const int NM = 6;
    for (int i = 0; i < NM; i++) {
        float fi = float(i);
        acc += luma(getB(vec2(fract(0.17 + fi * 0.618034), (fi + 0.5) / float(NM))).rgb);
    }
    return acc / float(NM);
}

float llEaseA(float p) { float x = clamp(p / LL_CUT, 0.0, 1.6); return x * x; }
float llEaseB(float p) { float x = clamp((1.0 - p) / (1.0 - LL_CUT), 0.0, 1.6); return pow(x, LL_EB); }

vec4 transition(vec2 uv) {
    float p = clamp(progress, 0.0, 1.0);
    float warmth = LL_WARM;

    // ---- envelope: strong ease-in into the cut, fast ease-out after it ----
    float env = p < LL_CUT ? pow(p / LL_CUT, 2.4) : pow(1.0 - (p - LL_CUT) / (1.0 - LL_CUT), LL_REL);
    float envW = env * env * env;
    // the light itself dies a little faster than the plate effects after the cut, so B clears quickly
    float envL = p < LL_CUT ? env : pow(1.0 - (p - LL_CUT) / (1.0 - LL_CUT), LL_RELL);

    // ---- leak-space coordinates ----
    float ang = radians(direction);
    vec2 d = vec2(cos(ang), sin(ang));
    vec2 nrm = vec2(-d.y, d.x);
    vec2 q = (uv - 0.5) * vec2(ratio, 1.0);
    float s = dot(q, d);
    float t = dot(q, nrm);
    float ext = 0.5 * (ratio * abs(d.x) + abs(d.y));
    float extT = 0.5 * (ratio * abs(nrm.x) + abs(nrm.y));   // frame half-extent across the drift

    // sweep position of the light mass (fastest at the cut)
    float ps = p < 0.5 ? 0.5 * pow(2.0 * p, 1.5) : 1.0 - 0.5 * pow(2.0 * (1.0 - p), 1.5);
    float c = mix(-1.3, 1.3, ps) * ext;

    // organic structure: domain-warped fbm that travels a bit slower than the mass (shape evolves)
    vec2 lc = vec2(s - c * 0.8, t) / max(ext, 0.3);
    float evo = p * 1.4;
    vec2 w1 = vec2(llFbm(lc * 0.8 + vec2(0.0, evo)), llFbm(lc * 0.8 + vec2(5.2, 1.3 - evo)));
    float f = llFbm(lc * 0.9 + w1 * 0.7 + vec2(evo * 0.6, 7.7));
    float f2 = llFbm(lc * 0.45 + w1 * 0.4 + vec2(11.3, evo * 0.4));

    // soft asymmetric mass: sharper leading edge, long trailing glow
    float ds = (s - c) / ext + 0.35 * f;
    float lead = 0.42;
    float trail = 0.8;
    float mass = ds > 0.0 ? exp(-(ds * ds) / (lead * lead)) : exp(-(ds * ds) / (trail * trail));
    float across = 0.7 + 0.55 * smoothstep(-0.9, 0.9, 1.3 * t / max(extT, 0.3) + 0.6 * f2);

    // soft streaks of light parallel to the front
    float fold = smoothstep(-0.1, 0.8, llNoise(vec2(lc.x * 2.6 + f * 0.8, lc.y * 0.45 + evo * 0.7)));

    // veiling wash that peaks at the cut (hides the swap), uneven like a real flare, thinner in the valleys
    float wash = envW * 0.42 * (0.75 + 0.7 * f2) * (0.7 + 0.6 * exp(-(ds * ds) / 2.2));

    float struct0 = mass * across * (0.9 + 0.9 * f) + 0.45 * fold * mass;
    wash *= LL_WASH_FLOOR + (1.0 - LL_WASH_FLOOR) * smoothstep(0.1, 0.8, struct0);
    float Dm = envL * intensity * LL_MASS * pow(max(struct0, 0.0), LL_POW);
    float Dw = envL * intensity * 0.95 * max(wash, 0.0);
    float Dl = Dm + Dw;

    // ---- plates: motion-blurred along their true trajectory + defocus at the peak ----
    float jit = llHash12(uv * resolution + vec2(17.0, 59.0) * fract(p * 7.31));
    float jang = jit * 6.2831853;
    float shutter = 0.04 * min(env * 6.0, 1.0);
    // defocus: A blooms out of focus into the cut, B arrives soft and racks into focus as the light leaves
    float radA = LL_DEF * pow(envL, LL_DEFP);
    float radB = LL_DEFB * pow(envL, LL_DEFPB);
    vec2 aspect = vec2(1.0 / ratio, 1.0);

    float leakN = clamp(struct0 * 0.6, 0.0, 1.0);
    float m = smoothstep(0.44, 0.56, p + (leakN - 0.5) * 0.08);

    const int NT = 16;
    vec3 accA = vec3(0.0);
    vec3 accB = vec3(0.0);
    vec3 hiA = vec3(0.0);
    vec3 hiB = vec3(0.0);
    bool needA = p < 0.62;
    bool needB = p > 0.38;
    for (int i = 0; i < NT; i++) {
        float fi = float(i);
        float k = (fi + fract(jit * 7.0 + fi * 0.618034)) / float(NT) - 0.5;
        float r = sqrt((fi + 0.5) / float(NT));
        float a = jang + fi * 2.3999632;
        vec2 disk = vec2(cos(a), sin(a)) * r * aspect;
        float pk = clamp(p + k * shutter, 0.0, 1.0);
        if (needA) {
            vec3 cA = llToLin(getA(llPlateUV(uv, llEaseA(pk), d, 1.0) + disk * radA).rgb);
            accA += cA;
            hiA += max(cA - 0.75, vec3(0.0));
        }
        if (needB) {
            vec3 cB = llToLin(getB(llPlateUV(uv, llEaseB(pk), d, -1.0) + disk * radB).rgb);
            accB += cB;
            hiB += max(cB - 0.75, vec3(0.0));
        }
    }
    float invN = 1.0 / float(NT);
    vec3 img = mix(accA, accB, m) * invN;
    vec3 hi = mix(hiA, hiB, m) * invN;
    float meanA = needA ? llMeanA() : 0.0;
    float meanB = needB ? llMeanB() : 0.0;
    float plateL = mix(meanA, meanB, smoothstep(0.4, 0.6, p));

    // ---- light ----
    // halation tint: red fringe -> orange -> gold, redder pockets where the light is thin
    vec3 wcol = mix(LL_W_O, LL_W_G, warmth);
    wcol = mix(wcol, vec3(1.0, 0.10, 0.03), 0.55 * smoothstep(0.05, 0.55, -f2) * (1.0 - 0.6 * warmth));

    // bright plates get less added light so their structure survives
    float adapt = mix(1.0, LL_ADAPT, smoothstep(0.30, 0.65, plateL));
    // leak exposure; the emulsion response saturates red first, green later, blue last (each with a toe), so the
    // light runs deep red at its thin edge -> orange -> gold -> warm white only in the hot core
    float X = (Dm + Dw) * LL_GAIN * adapt;
    // redder pockets where the light is thin, and the veiling wash is a deeper orange than the hot structure
    float deep = (1.0 - 0.5 * smoothstep(0.05, 0.55, -f2) * (1.0 - 0.6 * warmth)) * mix(0.75, 1.0, Dm / (Dm + Dw + 1e-4));
    float kG = mix(LL_KG_O, LL_KG_G, warmth) * deep;
    float kB = mix(LL_KB_O, LL_KB_G, warmth) * deep;
    vec3 lightWarm = vec3(1.0 - exp(-X), 1.0 - exp(-pow(X * kG, LL_NG) - LL_GLIN * X * kG), 1.0 - exp(-pow(X * kB, LL_NB)));
    // white light with the warm leak's exact silhouette: its brightness at every pixel is the warm light's luminance
    // (red edge dim, orange body brighter, hot core brightest), so the wave keeps its shape - only the hue goes
    vec3 light = mix(vec3(luma(lightWarm)), lightWarm, tint);
    // halation: only lamps / speculars bloom, and only inside the leak
    vec3 haloWarm = hi * wcol * 1.2 * env * smoothstep(0.05, 0.5, Dl);
    vec3 halo = mix(vec3(luma(haloWarm)), haloWarm, tint);

    // the plate goes through the leak's gel: a deep orange multiply that peaks with the leak (bright footage turns
    // orange-amber instead of cream), plus subtractive film-burn valleys where the leak is thin
    vec3 gelWarm = mix(LL_GEL_O, LL_GEL_G, warmth);
    vec3 gel = mix(vec3(luma(gelWarm)), gelWarm, tint);   // neutral: the same darkening of the plate under the light, no amber
    vec3 grade = mix(vec3(1.0), gel, LL_GEL_AMT * min(LL_GEL_ENV * env + (1.0 - exp(-LL_GEL_X * X)), 1.0));
    float valley = 1.0 - smoothstep(0.15, 0.6, struct0);
    vec3 burn = mix(vec3(1.0), mix(vec3(luma(LL_BURN)), LL_BURN, tint), 0.5 * env * env * valley) * (1.0 - LL_VALLEY * env * valley);
    // where the leak is dense it covers the picture (the light, not the plate, sets the colour there)
    float cover = LL_COVER * smoothstep(LL_COV0, LL_COV1, X);
    vec3 x = img * grade * burn * (1.0 - cover) * (1.0 + 0.10 * env) + light + halo;

    // hue-preserving shoulder: light keeps its hue as it rolls off (no lemon-cream clipping)
    vec3 y = llTone(x, 1.0 - LL_KNEE * env);
    vec3 col = llToGam(y);

    // ---- film grain (animated, ~1.4 px), fades with the leak; doubles as dither ----
    vec2 gp = uv * resolution / 1.4 + vec2(fract(p * 13.7) * 311.0, fract(p * 7.9) * 173.0);
    float g = llNoise(gp) * 0.7 + llNoise(gp * 1.9 + 4.1) * 0.3;
    float lum = luma(col);
    float gAmt = grain * env * 0.085 * (0.55 + 0.9 * lum * (1.0 - lum) * 2.0);
    float dith = (llHash12(uv * resolution + 3.7) - 0.5) / 255.0 * min(env * 8.0, 1.0);
    col += vec3(g * gAmt + dith);

    return vec4(clamp(col, 0.0, 1.0), 1.0);
}
